=0 AND (SELECT COUNT(*) FROM storage_entries se JOIN song_instances si ON si.id=se.instance_id AND si.source_id='r2-local' AND lower(si.suffix)='wav' JOIN song_masters sm ON sm.id=si.master_id WHERE se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-946c53a8d4b24847816c4a5e138be87f' AND sm.album_id!='pending-uploads' AND sm.id NOT IN (''))=0 AND (SELECT COUNT(*) FROM song_masters sm JOIN song_instances si ON si.master_id=sm.id JOIN storage_entries se ON se.instance_id=si.id AND se.kind='file' WHERE sm.id IN ('') AND sm.album_id IN ('') AND se.source_id='r2-local' AND se.parent_id='se-946c53a8d4b24847816c4a5e138be87f' AND lower(si.suffix)='wav')=0);
